starter_code:
class Membre:
    pass


def fiche_membre(nom, annee):
    return {}

solution:
class Membre:

    def __init__(self, nom, annee):
        self.nom = nom
        self.annee = annee


def fiche_membre(nom, annee):
    membre = Membre(nom, annee)
    return {"nom": membre.nom, "annee": membre.annee}

