class Dossier:

    def __init__(self, nom, notes):
        self.nom = nom
        self.notes = notes


def comparer_dossiers(nom, notes, nouvelle_note):
    premier = Dossier(nom, notes)
    second = Dossier(nom, notes)
    premier.notes.append(nouvelle_note)
    return {
        "premier": {"nom": premier.nom, "notes": premier.notes},
        "second": {"nom": second.nom, "notes": second.notes},
    }

solution:
class Dossier:

    def __init__(self, nom, notes):
        self.nom = nom
        self.notes = list(notes)


def comparer_dossiers(nom, notes, nouvelle_note):
    premier = Dossier(nom, notes)
    second = Dossier(nom, notes)
    premier.notes.append(nouvelle_note)
    return {
        "premier": {"nom": premier.nom, "notes": premier.notes},
        "second": {"nom": second.nom, "notes": second.notes},
    }

